use std::{future::Future,io::Write,sync::Arc,task::{Context,Poll,Wake,Waker},time::Duration};
struct TW(std::thread::Thread);impl Wake for TW{fn wake(self:Arc<Self>){self.0.unpark();}fn wake_by_ref(self:&Arc<Self>){self.0.unpark();}}
fn block_on<T>(f:impl Future<Output=T>)->T{let mut f=std::pin::pin!(f);let w=Waker::from(Arc::new(TW(std::thread::current())));let mut cx=Context::from_waker(&w);loop{match f.as_mut().poll(&mut cx){Poll::Ready(v)=>return v,Poll::Pending=>std::thread::park_timeout(Duration::from_millis(1))}}}
fn save(p:&std::path::Path,b:&[u8]){let mut f=std::fs::OpenOptions::new().write(true).create_new(true).open(p).unwrap();f.write_all(b).unwrap();f.sync_all().unwrap();}
fn main(){
 let args:Vec<_>=std::env::args().collect();let request:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let instance=wgpu::Instance::new(wgpu::InstanceDescriptor{backends:wgpu::Backends::DX12,..wgpu::InstanceDescriptor::new_without_display_handle()});
 let adapter=block_on(instance.request_adapter(&wgpu::RequestAdapterOptions{power_preference:wgpu::PowerPreference::HighPerformance,force_fallback_adapter:false,compatible_surface:None})).unwrap();let info=adapter.get_info();assert_eq!(info.backend,wgpu::Backend::Dx12);assert!(adapter.features().contains(wgpu::Features::FLOAT32_FILTERABLE));let(device,queue)=block_on(adapter.request_device(&wgpu::DeviceDescriptor{label:Some("Actual House full surface numeric parity"),required_features:wgpu::Features::FLOAT32_FILTERABLE,required_limits:adapter.limits(),..Default::default()})).unwrap();let mut receipts=Vec::new();
 for row in request["materials"].as_array().unwrap(){
  let data=std::fs::read(row["input"].as_str().unwrap()).unwrap();let count=row["samples"].as_u64().unwrap();assert_eq!(data.len() as u64,count*80);let source=std::fs::read_to_string(row["wgsl_path"].as_str().unwrap()).unwrap();
  let module=device.create_shader_module(wgpu::ShaderModuleDescriptor{label:Some("Native bound source House surface"),source:wgpu::ShaderSource::Wgsl(source.into())});let pipeline=device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor{label:None,layout:None,module:&module,entry_point:Some("surface"),compilation_options:Default::default(),cache:None});
  let mut views=Vec::new();let mut samplers=Vec::new();for name in ["_L1_Height","_L1_Albedo","_L1_Normal"]{
   let texture_row=row["textures"].as_array().unwrap().iter().find(|r|r["property"].as_str().unwrap()==name).unwrap();let width=texture_row["width"].as_u64().unwrap() as u32;let height=texture_row["height"].as_u64().unwrap() as u32;let bytes=std::fs::read(texture_row["raw_output"].as_str().unwrap()).unwrap();assert_eq!(bytes.len(),(width*height*16) as usize);
   assert_eq!(texture_row["filter"],"Bilinear");assert_eq!(texture_row["wrap_u"],"Repeat");assert_eq!(texture_row["wrap_v"],"Repeat");assert_eq!(texture_row["aniso"],1);
   let texture=device.create_texture(&wgpu::TextureDescriptor{label:Some(name),size:wgpu::Extent3d{width,height,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba32Float,usage:wgpu::TextureUsages::TEXTURE_BINDING|wgpu::TextureUsages::COPY_DST,view_formats:&[]});queue.write_texture(wgpu::TexelCopyTextureInfo{texture:&texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},&bytes,wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(width*16),rows_per_image:Some(height)},wgpu::Extent3d{width,height,depth_or_array_layers:1});views.push(texture.create_view(&Default::default()));samplers.push(device.create_sampler(&wgpu::SamplerDescriptor{address_mode_u:wgpu::AddressMode::Repeat,address_mode_v:wgpu::AddressMode::Repeat,min_filter:wgpu::FilterMode::Linear,mag_filter:wgpu::FilterMode::Linear,lod_min_clamp:0.0,lod_max_clamp:0.0,..Default::default()}));
  }
  let input=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:data.len() as u64,usage:wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});queue.write_buffer(&input,0,&data);let size=count*80;let output=device.create_buffer(&wgpu::BufferDescriptor{label:None,size,usage:wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_SRC,mapped_at_creation:false});let readback=device.create_buffer(&wgpu::BufferDescriptor{label:None,size,usage:wgpu::BufferUsages::MAP_READ|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});
  let mut entries=Vec::new();for i in 0..3{entries.push(wgpu::BindGroupEntry{binding:(2*i) as u32,resource:wgpu::BindingResource::TextureView(&views[i])});entries.push(wgpu::BindGroupEntry{binding:(2*i+1) as u32,resource:wgpu::BindingResource::Sampler(&samplers[i])});}entries.push(wgpu::BindGroupEntry{binding:6,resource:input.as_entire_binding()});entries.push(wgpu::BindGroupEntry{binding:7,resource:output.as_entire_binding()});let binding=device.create_bind_group(&wgpu::BindGroupDescriptor{label:None,layout:&pipeline.get_bind_group_layout(0),entries:&entries});
  let mut encoder=device.create_command_encoder(&Default::default());{let mut pass=encoder.begin_compute_pass(&wgpu::ComputePassDescriptor{label:None,timestamp_writes:None});pass.set_pipeline(&pipeline);pass.set_bind_group(0,&binding,&[]);pass.dispatch_workgroups((count as u32).div_ceil(64),1,1);}encoder.copy_buffer_to_buffer(&output,0,&readback,0,size);let submission=queue.submit([encoder.finish()]);let(tx,rx)=std::sync::mpsc::channel();readback.slice(..).map_async(wgpu::MapMode::Read,move|r|tx.send(r).unwrap());device.poll(wgpu::PollType::Wait{submission_index:Some(submission),timeout:Some(Duration::from_secs(30))}).unwrap();rx.recv_timeout(Duration::from_secs(30)).unwrap().unwrap();let mapped=readback.slice(..).get_mapped_range();for b in mapped.chunks_exact(4){assert!(f32::from_le_bytes(b.try_into().unwrap()).is_finite());}let path=std::path::Path::new(&args[2]).join(format!("{}.f32",row["guid"].as_str().unwrap()));save(&path,&mapped);drop(mapped);readback.unmap();receipts.push(serde_json::json!({"guid":row["guid"],"samples":count,"output":path,"output_bytes":size}));
 }
 let receipt=serde_json::json!({"adapter":info.name,"backend":format!("{:?}",info.backend),"driver":info.driver,"materials":receipts,"texture_storage":"Actual native GPU-decoded RGBA mip0, uploaded as Rgba32Float without extra color conversion","implicit_derivative_lod_verified":false,"full_import":false});save(std::path::Path::new(&args[3]),&serde_json::to_vec_pretty(&receipt).unwrap());println!("{}",receipt);
}
